from amazon.textract import AmazonTextract

def validate_document_fields(document_bytes):
    client = AmazonTextract.Client()
    response = client.analyze_document(
        Document={'Bytes': document_bytes},
        FeatureTypes=['FORMS']
    )

    required_fields = ['customer_name', 'invoice_number', 'total_amount']
    extracted_fields = {item['KeyDetection']['Text']: item['ValueDetection']['Text'] for item in response['Blocks'] if item['BlockType'] == 'KEY_VALUE_SET'}

    for field in required_fields:
        if field not in extracted_fields:
            return False, f"Missing required field: {field}"

        field_value = extracted_fields[field]
        if not field_value:
            return False, f"Empty value for required field: {field}"

        field_confidence = next(item['Confidence'] for item in response['Blocks'] if item['BlockType'] == 'KEY_VALUE_SET' and item['KeyDetection']['Text'] == field)
        if field_confidence < 80:
            return False, f"Low confidence score for field: {field}"

    return True, "All required fields validated successfully"
